1441	// 开放不足资源的统一展示：资源行 + 相关有效停用（标识与时间）
1442	function gapLines(gaps: CoverageGap[], indent: string): string[] {
1443	  const lines: string[] = [];
1444	  for (const g of gaps) {
1445	    lines.push(`${indent}- ${g.id}（${g.r.name}）`);
1446	    for (const c of g.closures) {
1447	      lines.push(`${indent}  相关有效停用: ${c.id}（${c.start} → ${c.end}）`);
1448	    }
1449	  }
1450	  return lines;
1451	}
