1453	// 校验每个资源的实际可用时间都能完整覆盖 [startMin, endMin)
1454	function assertOpenCoverage(store: Store, ids: string[], startMin: number, endMin: number): void {
1455	  const failing = findCoverageGaps(store, ids, startMin, endMin);
1456	  if (failing.length > 0) {
1457	    throw new BizError(
1458	      '开放时间不足，以下资源的实际可用时间（开放区间扣除有效停用）不能完整覆盖预约区间：\n' +
1459	        gapLines(failing, '').join('\n'),
1460	    );
1461	  }
1462	}
