114	  id: string,
115	  start: string,
116	  end: string,
117	  resources: string[],
118	  ctx: string,
119	): void {
120	  const b = bookingOf(store, id);
121	  assert.equal(b.start, start, `[${ctx}] ${id} 开始时间`);
122	  assert.equal(b.end, end, `[${ctx}] ${id} 结束时间`);
123	  assert.deepEqual(b.resourceIds, [...resources].sort(), `[${ctx}] ${id} 资源集合`);
124	}
125	
126	function assertFileBytes(df: string, expected: Buffer, ctx: string): void {
127	  assert.ok(expected.equals(readFileSync(df)), `[${ctx}] 数据文件应逐字节保留`);
128	}
129	
130	// ---------------------------------------------------------------------------
131	// 1. 整批交换成功（逐项会被对方旧占用阻挡，整批可行）与真实批内冲突
132	// ---------------------------------------------------------------------------
133	
134	test('批量改期：整批交换时段成功；真实批内冲突双方互列且整批不变', (t) => {
135	  const dir = tempDir(t);
136	  const df = join(dir, 'data.json');
137	  addResource(df, '甲'); // R0001
138	  createBooking(df, ['R0001'], '2026-10-12T09:00', '2026-10-12T10:00', 'B0001');
139	  createBooking(df, ['R0001'], '2026-10-12T10:00', '2026-10-12T11:00', 'B0002');
140	
141	  // 交换时段：逐项改期会被对方旧占用阻挡，整批校验排除本批占用后可行
142	  const swap = writeManifest(dir, 'swap.json', [
143	    {bookingId: 'B0001', start: '2026-10-12T10:00', end: '2026-10-12T11:00', resourceIds: ['R0001']},
144	    {bookingId: 'B0002', start: '2026-10-12T09:00', end: '2026-10-12T10:00', resourceIds: ['R0001']},
145	  ]);
146	  const r1 = ok(df, ['reschedule-batch', swap], '整批交换时段');
147	  assert.match(r1.stdout, /O0001/);
148	  let store = readStore(df);
149	  assertArrangement(store, 'B0001', '2026-10-12T10:00', '2026-10-12T11:00', ['R0001'], '交换后');
150	  assertArrangement(store, 'B0002', '2026-10-12T09:00', '2026-10-12T10:00', ['R0001'], '交换后');
151	  // 由新进程回读保存结果
152	  const dayView = ok(df, ['list-bookings', '--date', '2026-10-12'], '新进程按日查询');
153	  assert.match(dayView.stdout, /B0001 \[已预约\] 2026-10-12T10:00 → 2026-10-12T11:00/);
154	  assert.match(dayView.stdout, /B0002 \[已预约\] 2026-10-12T09:00 → 2026-10-12T10:00/);
155	
156	  // 真实批内冲突：两项目标在同一资源上时间重叠，双方都报告对方
157	  const clash = writeManifest(dir, 'clash.json', [
158	    {bookingId: 'B0001', start: '2026-10-12T14:00', end: '2026-10-12T15:00', resourceIds: ['R0001']},
159	    {bookingId: 'B0002', start: '2026-10-12T14:30', end: '2026-10-12T15:30', resourceIds: ['R0001']},
160	  ]);
161	  const bytesBefore = readFileSync(df);
162	  const r2 = bizFail(df, ['reschedule-batch', clash], '真实批内冲突');
163	  assert.match(r2.stderr, /共 2 项不满足条件/);
164	  assert.match(r2.stderr, /第 1 项 B0001 目标 2026-10-12T14:00 → 2026-10-12T15:00/);
165	  assert.match(r2.stderr, /第 2 项 B0002 目标 2026-10-12T14:30 → 2026-10-12T15:30/);
166	  assert.match(
167	    r2.stderr,
168	    /B0002（本批第 2 项目标 2026-10-12T14:30 → 2026-10-12T15:30）：共同资源 R0001/,
169	    '第 1 项列出对方标识与目标时间',
170	  );
171	  assert.match(
172	    r2.stderr,
173	    /B0001（本批第 1 项目标 2026-10-12T14:00 → 2026-10-12T15:00）：共同资源 R0001/,
174	    '第 2 项列出对方标识与目标时间',
175	  );
176	  assertFileBytes(df, bytesBefore, '批内冲突逐字节保留');
177	  store = readStore(df);
178	  assertArrangement(store, 'B0001', '2026-10-12T10:00', '2026-10-12T11:00', ['R0001'], '整批不变');
179	  assertArrangement(store, 'B0002', '2026-10-12T09:00', '2026-10-12T10:00', ['R0001'], '整批不变');
180	  assert.equal(store.batchOps.length, 1, '不留新操作记录');
181	  assert.equal(store.batchSeq, 1, '操作计数不变');
182	});
