210	  assert.ok(i1 >= 0 && i2 > i1 && i3 > i2, '失败项按清单顺序而非标识顺序报告');
211	  assert.match(r.stderr, /第 1 项 B0003[\s\S]*?B0004（2026-10-12T14:00 → 2026-10-12T15:00）/, '批外冲突');
