373	  assert.equal(store.batchOps.length, 0, '不留操作记录');
374	  assert.equal(store.batchSeq, 0, '标识未消费');
375	
376	  // (d) 同一原数据在可保存位置重试：成功且操作标识未被失败尝试消费
377	  const retryFile = join(dir, 'retry.json');
378	  writeFileSync(retryFile, origBytes);
379	  const r4 = ok(retryFile, ['reschedule-batch', change], '可保存位置重试');
380	  assert.match(r4.stdout, /O0001/, '标识未被消费，仍为 O0001');
381	  store = readStore(retryFile);
382	  assertArrangement(store, 'B0001', '2026-10-12T14:00', '2026-10-12T15:00', ['R0001'], '重试生效');
383	  assert.equal(store.batchSeq, 1);
384	  const opsView = ok(retryFile, ['list-batch-ops'], '新进程查询操作记录');
385	  assert.match(opsView.stdout, /O0001 \[未撤销\]/);
386	});
