        `连续 ${durationMinutes} 分钟时段（各组须各选一个互不相同的候选资源并全程保持）。`,
    );
    return;
  }
  const startRaw = formatDateTime(found.startMin)!;
  const endRaw = formatDateTime(found.endMin)!;
